CREATE TABLE notification_template(id BIGINT NOT NULL,code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,title_template VARCHAR(200) NOT NULL,content_template TEXT NOT NULL,channel VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'IN_APP',enabled BOOLEAN NOT NULL DEFAULT TRUE,version BIGINT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_notification_template_code(code));
CREATE TABLE notification_message(id BIGINT NOT NULL,event_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,user_id BIGINT NOT NULL,template_code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,title VARCHAR(200) NOT NULL,content TEXT NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'PENDING',retry_count INT UNSIGNED NOT NULL DEFAULT 0,next_retry_at DATETIME(6) NULL,last_error VARCHAR(1000) NULL,read_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),sent_at DATETIME(6) NULL,PRIMARY KEY(id),UNIQUE KEY uk_notification_event_user(event_id,user_id),INDEX idx_notification_user_read(user_id,read_at,created_at),INDEX idx_notification_dispatch(status,next_retry_at));
CREATE TABLE notification_dead_letter(id BIGINT NOT NULL,message_id BIGINT NOT NULL,event_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,failure_reason VARCHAR(1000) NOT NULL,payload_json JSON NOT NULL,failed_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_notification_dead_message(message_id));
INSERT INTO notification_template(id,code,title_template,content_template) VALUES(1,'ORDER_PAID','订单支付成功','您的订单 {{referenceId}} 已使用模拟余额支付成功。'),(2,'TRAINING_ASSIGNED','新的培训任务','您有新的培训任务：{{courseTitle}}。');
